const MANIFEST = Object.fromEntries(FILES.map(([f, h]) => [f, h]));
const BYTES = FILES.reduce((n, f) => n + f[2], 0), BATCH = 4 * 2 ** 20;
const tell = async m => (await self.clients.matchAll({ includeUncontrolled: true })).forEach(c => c.postMessage(m));
const manifest = async c => (await c.match("__saved__"))?.json().catch(() => ({}));
const current = hashes => hashes && JSON.stringify(hashes) === JSON.stringify(MANIFEST);

async function saved() {
  const cache = await caches.open(CACHE);
  if (await manifest(cache)) return cache;
  // CacheStorage cannot rename: migrate the existing saved copy once, without downloading it again.
  for (const name of await caches.keys()) {
    if (!name.startsWith("loth-wiki-") || name === CACHE || name === STAGING) continue;
    const old = await caches.open(name), hashes = await manifest(old);
    if (!hashes) continue;
    for (const key of await old.keys()) {
      if (new URL(key.url).pathname.endsWith("/__saved__")) continue;
      await cache.put(key, await old.match(key));
    }
    await cache.put("__saved__", new Response(JSON.stringify(hashes)));
    return cache;
  }
  return cache;
}

async function save() {
  const cache = await saved(), hashes = await manifest(cache), update = !!hashes;
  let stage = await caches.open(STAGING);
  if (!current(await manifest(stage))) {
    await caches.delete(STAGING);
    stage = await caches.open(STAGING);
    await stage.put("__saved__", new Response(JSON.stringify(MANIFEST)));
  }
  const keys = new Set((await stage.keys()).map(k => k.url));
  const changed = FILES.filter(([f, h]) => hashes?.[f] !== h);
  const todo = changed.filter(([f]) => !keys.has(new URL(f, self.registration.scope).href)), batch = [];
  let have = BYTES - todo.reduce((n, f) => n + f[2], 0), size = 0;
  while (todo.length && size < BATCH) { const t = todo.shift(); batch.push(t); size += t[2]; }
  const fetched = batch.length;
  let stop;
  await Promise.all(Array.from({ length: 3 }, async () => {
    for (let t; !stop && (t = batch.shift());) {
      try {
        const r = await fetch(t[0], { cache: "no-cache" });
        if (!r.ok) throw new Error(`${t[0]}: ${r.status}`);
        await stage.put(t[0], r);
        have += t[2];
        if (!stop && batch.length % 20 === 0) await tell({ kind: "progress", have, bytes: BYTES, update });
      } catch (err) { stop ||= err; }
    }
  }));
  if (stop) throw stop;
  if (!todo.length) {
    for (const [f] of changed) await cache.put(f, await stage.match(f));
    for (const f of Object.keys(hashes || {})) if (!(f in MANIFEST)) await cache.delete(f);
    await cache.put("__saved__", new Response(JSON.stringify(MANIFEST)));
    await caches.delete(STAGING);
    for (const name of await caches.keys()) {
      if (name.startsWith("loth-wiki-") && name !== CACHE) await caches.delete(name);
    }
    self.skipWaiting();
  }
  await tell({ kind: "batch", fetched, fetchedBytes: size, left: todo.length, update });
}

let running;  // one save at a time: a second ask (another tab, a status and a tap) joins it
const once = () => running ||= save().catch(err => tell({ kind: "error", text: err.message })).finally(() => { running = null; });
self.addEventListener("install", e => e.waitUntil(saved().then(manifest).then(hashes => hashes ? once() : self.skipWaiting())));
self.addEventListener("activate", e => e.waitUntil(self.clients.claim()));
self.addEventListener("message", e => {
  if (e.data === "save") e.waitUntil(once());
  if (e.data === "status") e.waitUntil(saved().then(manifest)
    .then(hashes => e.source.postMessage({ kind: "status", saved: !!current(hashes), update: !!hashes && !current(hashes), bytes: BYTES })));
});
self.addEventListener("fetch", e => {
  if (e.request.method !== "GET") return;
  const url = new URL(e.request.url), referrer = e.request.referrer ? new URL(e.request.referrer) : null;
  // Saved builds and release archives always come from the network. The planner and what it loads try the network first
  // (a build link must reach its own release's calculator), then the offline copy, so the planner still opens offline;
  // an archived release's own files are never answered from the cache, so it can't show another release's values offline.
  if (/\/(?:api|b)\//.test(url.pathname)) return;
  if (/\/builds\.html$/.test(url.pathname) || url.searchParams.has("release") || url.searchParams.has("current") || referrer?.pathname.endsWith("/builds.html")) {
    e.respondWith(fetch(e.request).catch(() => url.searchParams.has("release") ? Response.error() : caches.match(e.request, { cacheName: CACHE, ignoreSearch: true })
      .then(hit => hit || Response.error())));
    return;
  }
  e.respondWith(caches.match(e.request, { cacheName: CACHE, ignoreSearch: true })
    .then(hit => hit || fetch(e.request)
    .catch(() => {
      if (e.request.mode !== "navigate") return Response.error();
      const path = new URL(e.request.url).pathname;
      const item = path.match(/\/drops\/([^/]+?)(?:\.html)?$/);
      if (item) return Response.redirect(new URL(`item/${item[1]}.html`, self.registration.scope), 302);
      return caches.match("index.html", { cacheName: CACHE });
    })));
});
